            int[] opp = new int[7];
            opp[A] = F; opp[F] = A;
            opp[B] = D; opp[D] = B;
            opp[C] = E; opp[E] = C;

            int[] faces = {A, B, C, D, E, F};
            int[] newDp = new int[7];
            Arrays.fill(newDp, Integer.MIN_VALUE);

            for (int b = 1; b <= 6; b++) {
                int t = opp[b];
                int maxLat = 0;
                for (int f : faces) {
                    if (f != b && f != t) {
                        if (f > maxLat) maxLat = f;
                    }
                }
                if (dp[b] != Integer.MIN_VALUE) {
                    int val = dp[b] + maxLat;
                    if (val > newDp[t]) newDp[t] = val;
                }
            }
            dp = newDp;
        }

        int ans = 0;
        for (int t = 1; t <= 6; t++) {
            if (dp[t] > ans) ans = dp[t];
        }
        System.out.println(ans);
    }
}
